using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Identity; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using SmartRental.Data; using SmartRental.Models;
namespace SmartRental.Controllers;
[Authorize] public class ThongBaoController:Controller { private readonly ApplicationDbContext _db; private readonly UserManager<ApplicationUser> _users; public ThongBaoController(ApplicationDbContext db,UserManager<ApplicationUser> users){_db=db;_users=users;} public async Task<IActionResult> Index(){var id=_users.GetUserId(User)!;return View(await _db.ThongBaos.Where(x=>x.UserId==id).OrderByDescending(x=>x.NgayTao).ToListAsync());} [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Read(int id){var n=await _db.ThongBaos.FindAsync(id);if(n is null)return NotFound();if(n.UserId!=_users.GetUserId(User))return Forbid();n.DaDoc=true;await _db.SaveChangesAsync();return Redirect(n.Link??Url.Action(nameof(Index))!);} }
